<section class="panel demographic-card gender-panel" aria-labelledby="gender-heading"><div class="panel-heading"><div><div class="eyebrow muted">BERDASARKAN JENIS KELAMIN</div><h2 id="gender-heading">Komposisi pegawai berdasarkan jenis kelamin</h2></div><span class="badge neutral" id="gender-scope">Keseluruhan</span></div><div class="gender-visual"><svg class="gender-donut" viewBox="0 0 180 180" role="img" aria-label="Proporsi jenis kelamin"><circle class="donut-track" cx="90" cy="90" r="70"/><g transform="rotate(-90 90 90)"><?php $offset=0; foreach(['male','female'] as $genderKey): $share=$genderTotal?100*$dashboard['all']['genders'][$genderKey]/$genderTotal:0; ?><circle class="donut-segment donut-<?=e($genderKey)?>" data-donut="<?=e($genderKey)?>" cx="90" cy="90" r="70" pathLength="100" stroke-dasharray="<?=e($share)?> <?=e(100-$share)?>" stroke-dashoffset="<?=e(-$offset)?>"/><?php $offset+=$share; endforeach ?></g></svg><div class="gender-total"><strong id="demographic-total"><?=$genderTotal?></strong><span>pegawai</span></div></div><div class="chart-bars"><?php foreach($genderLabels as $key=>$label): $n=$dashboard['all']['genders'][$key]; ?><div class="chart-row" data-group="genders" data-key="<?=e($key)?>"><div class="chart-row-heading"><strong><?=e($label)?></strong><output><?=$n?> pegawai</output></div><progress class="gender-<?=e($key)?>" value="<?=$n?>" max="<?=max(1,array_sum($dashboard['all'][isset($generationRanges[$key])?'generations':'genders']))?>" aria-label="<?=e($label)?>: <?=$n?> pegawai"></progress></div><?php endforeach ?></div><p class="chart-footnote"><span id="gender-coverage">Mencakup <?=$genderTotal?> dari <?=$total?> pegawai.</span></p></section>
